[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>SnapFrame — Capture, Create & Share What You Love</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
    <style>
        *, *::before, *::after {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        :root {
            --black: #000000;
            --purple: #7638FA;
            --orange: #FF7A00;
            --white: #FFFFFF;
            --gray-50: #F9FAFB;
            --gray-100: #F3F4F6;
            --gray-200: #E5E7EB;
            --gray-300: #D1D5DB;
            --gray-400: #9CA3AF;
            --gray-500: #6B7280;
            --gray-600: #4B5563;
            --gray-700: #374151;
            --gray-800: #1F2937;
            --gray-900: #111827;
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            background: var(--white);
            color: var(--gray-900);
            line-height: 1.6;
            overflow-x: hidden;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        /* Header */
        .header {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            z-index: 1000;
            background: rgba(255, 255, 255, 0.95);
            backdrop-filter: blur(10px);
            border-bottom: 1px solid var(--gray-100);
        }

        .header-inner {
            max-width: 1280px;
            margin: 0 auto;
            padding: 0 24px;
            height: 64px;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .logo {
            font-size: 24px;
            font-weight: 800;
            color: var(--black);
            display: flex;
            align-items: center;
            gap: 2px;
        }

        .logo-icon {
            width: 28px;
            height: 28px;
            background: linear-gradient(135deg, var(--purple), var(--orange));
            border-radius: 6px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .logo-icon span {
            color: white;
            font-size: 16px;
            font-weight: 700;
        }

        .nav-desktop {
            display: flex;
            align-items: center;
            gap: 32px;
        }

        .nav-links {
            display: flex;
            gap: 24px;
        }

        .nav-links a {
            font-size: 14px;
            font-weight: 500;
            color: var(--gray-600);
            transition: color 0.2s;
        }

        .nav-links a:hover {
            color: var(--black);
        }

        .btn-login {
            padding: 10px 20px;
            background: var(--black);
            color: var(--white);
            font-size: 14px;
            font-weight: 600;
            border-radius: 20px;
            transition: all 0.2s;
        }

        .btn-login:hover {
            background: var(--gray-800);
            transform: translateY(-1px);
        }

        .hamburger {
            display: none;
            flex-direction: column;
            justify-content: center;
            gap: 5px;
            width: 40px;
            height: 40px;
            cursor: pointer;
            padding: 8px;
            border-radius: 8px;
            transition: background 0.2s;
        }

        .hamburger:hover {
            background: var(--gray-100);
        }

        .hamburger span {
            display: block;
            width: 20px;
            height: 2px;
            background: var(--black);
            border-radius: 2px;
            transition: all 0.3s;
        }

        .hamburger.active span:nth-child(1) {
            transform: rotate(45deg) translate(5px, 5px);
        }

        .hamburger.active span:nth-child(2) {
            opacity: 0;
        }

        .hamburger.active span:nth-child(3) {
            transform: rotate(-45deg) translate(5px, -5px);
        }

        /* Mobile Menu */
        .mobile-menu {
            display: none;
            position: fixed;
            top: 64px;
            left: 0;
            right: 0;
            bottom: 0;
            background: var(--white);
            z-index: 999;
            padding: 24px;
            flex-direction: column;
            gap: 8px;
            overflow-y: auto;
        }

        .mobile-menu.active {
            display: flex;
        }

        .mobile-menu a {
            display: block;
            padding: 16px;
            font-size: 16px;
            font-weight: 500;
            color: var(--gray-700);
            border-radius: 12px;
            transition: all 0.2s;
        }

        .mobile-menu a:hover {
            background: var(--gray-50);
            color: var(--black);
        }

        .mobile-menu .btn-login {
            margin-top: 16px;
            text-align: center;
        }

        /* Hero Section */
        .hero {
            padding: 140px 24px 100px;
            background: linear-gradient(135deg, #fef7f0 0%, #fdf2ff 50%, #f0f4ff 100%);
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .hero::before {
            content: '';
            position: absolute;
            top: -50%;
            left: -50%;
            width: 200%;
            height: 200%;
            background: radial-gradient(circle at 30% 20%, rgba(118, 56, 250, 0.1) 0%, transparent 50%),
                        radial-gradient(circle at 70% 80%, rgba(255, 122, 0, 0.1) 0%, transparent 50%);
            animation: float 20s ease-in-out infinite;
        }

        @keyframes float {
            0%, 100% { transform: translate(0, 0) rotate(0deg); }
            50% { transform: translate(-2%, -2%) rotate(1deg); }
        }

        .hero-content {
            position: relative;
            max-width: 800px;
            margin: 0 auto;
        }

        .hero h1 {
            font-size: clamp(36px, 6vw, 64px);
            font-weight: 900;
            line-height: 1.1;
            color: var(--black);
            margin-bottom: 24px;
            letter-spacing: -0.02em;
        }

        .hero p {
            font-size: clamp(18px, 2.5vw, 22px);
            color: var(--gray-600);
            margin-bottom: 40px;
            max-width: 600px;
            margin-left: auto;
            margin-right: auto;
        }

        .hero-cta {
            display: inline-flex;
            align-items: center;
            gap: 12px;
            padding: 16px 32px;
            background: linear-gradient(135deg, var(--purple), #9b59f7);
            color: var(--white);
            font-size: 16px;
            font-weight: 700;
            border-radius: 30px;
            box-shadow: 0 4px 20px rgba(118, 56, 250, 0.4);
            transition: all 0.3s;
        }

        .hero-cta:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 30px rgba(118, 56, 250, 0.5);
        }

        .hero-cta svg {
            transition: transform 0.2s;
        }

        .hero-cta:hover svg {
            transform: translateX(4px);
        }

        /* Section Styles */
        .section {
            padding: 80px 24px;
        }

        .section-inner {
            max-width: 1200px;
            margin: 0 auto;
        }

        .section-header {
            margin-bottom: 40px;
        }

        .section-label {
            display: inline-block;
            padding: 6px 14px;
            background: var(--gray-100);
            color: var(--gray-600);
            font-size: 12px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            border-radius: 20px;
            margin-bottom: 16px;
        }

        .section-title {
            font-size: clamp(28px, 4vw, 40px);
            font-weight: 800;
            color: var(--black);
            line-height: 1.2;
            margin-bottom: 16px;
        }

        .section-title.gradient-text {
            background: linear-gradient(135deg, var(--purple), var(--orange));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .section-desc {
            font-size: 18px;
            color: var(--gray-600);
            max-width: 700px;
            line-height: 1.7;
        }

        .section-link {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            margin-top: 24px;
            font-size: 16px;
            font-weight: 600;
            color: var(--purple);
            transition: gap 0.2s;
        }

        .section-link:hover {
            gap: 12px;
        }

        .section-link svg {
            transition: transform 0.2s;
        }

        .section-link:hover svg {
            transform: translateX(4px);
        }

        /* Features Section */
        .features {
            background: var(--gray-50);
        }

        .features-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 24px;
            margin-top: 48px;
        }

        .feature-card {
            background: var(--white);
            padding: 32px;
            border-radius: 16px;
            border: 1px solid var(--gray-100);
            transition: all 0.3s;
        }

        .feature-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 12px 40px rgba(0, 0, 0, 0.08);
            border-color: transparent;
        }

        .feature-icon {
            width: 48px;
            height: 48px;
            background: linear-gradient(135deg, var(--purple), var(--orange));
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 20px;
        }

        .feature-icon svg {
            width: 24px;
            height: 24px;
            color: var(--white);
        }

        .feature-card h3 {
            font-size: 18px;
            font-weight: 700;
            color: var(--black);
            margin-bottom: 8px;
        }

        .feature-card p {
            font-size: 14px;
            color: var(--gray-500);
            line-height: 1.6;
        }

        /* Safety Section */
        .safety {
            background: linear-gradient(180deg, #f0f9ff 0%, var(--white) 100%);
        }

        .safety-content {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 60px;
            align-items: center;
        }

        .safety-visual {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 16px;
        }

        .safety-item {
            background: var(--white);
            padding: 24px;
            border-radius: 16px;
            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06);
            text-align: center;
            transition: transform 0.3s;
        }

        .safety-item:hover {
            transform: scale(1.02);
        }

        .safety-item-icon {
            width: 48px;
            height: 48px;
            background: linear-gradient(135deg, #10b981, #059669);
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 0 auto 12px;
        }

        .safety-item-icon svg {
            width: 24px;
            height: 24px;
            color: var(--white);
        }

        .safety-item span {
            font-size: 14px;
            font-weight: 600;
            color: var(--gray-700);
        }

        /* Creators Section */
        .creators {
            background: linear-gradient(135deg, var(--black) 0%, #1a1a2e 100%);
            color: var(--white);
        }

        .creators .section-label {
            background: rgba(255, 255, 255, 0.1);
            color: var(--white);
        }

        .creators .section-title {
            color: var(--white);
        }

        .creators .section-desc {
            color: var(--gray-300);
        }

        .creators .section-link {
            color: var(--orange);
        }

        .creators-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 24px;
            margin-top: 48px;
        }

        .creator-card {
            background: rgba(255, 255, 255, 0.05);
            backdrop-filter: blur(10px);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 20px;
            padding: 32px;
            transition: all 0.3s;
        }

        .creator-card:hover {
            background: rgba(255, 255, 255, 0.08);
            transform: translateY(-4px);
        }

        .creator-card-icon {
            width: 56px;
            height: 56px;
            background: linear-gradient(135deg, var(--purple), var(--orange));
            border-radius: 14px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 20px;
        }

        .creator-card-icon svg {
            width: 28px;
            height: 28px;
            color: var(--white);
        }

        .creator-card h3 {
            font-size: 20px;
            font-weight: 700;
            margin-bottom: 8px;
        }

        .creator-card p {
            font-size: 14px;
            color: var(--gray-400);
            line-height: 1.6;
        }

        /* Tagline Banner */
        .tagline-banner {
            background: linear-gradient(135deg, var(--purple), var(--orange));
            padding: 60px 24px;
            text-align: center;
        }

        .tagline-text {
            font-size: clamp(24px, 4vw, 36px);
            font-weight: 800;
            color: var(--white);
            max-width: 800px;
            margin: 0 auto;
            line-height: 1.3;
        }

        /* News Section */
        .news {
            background: var(--gray-50);
        }

        .news-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 40px;
            flex-wrap: wrap;
            gap: 16px;
        }

        .news-carousel {
            display: flex;
            gap: 24px;
            overflow-x: auto;
            padding-bottom: 20px;
            margin: 0 -24px;
            padding-left: 24px;
            padding-right: 24px;
            scroll-snap-type: x mandatory;
            -webkit-overflow-scrolling: touch;
            scrollbar-width: none;
        }

        .news-carousel::-webkit-scrollbar {
            display: none;
        }

        .news-card {
            flex: 0 0 340px;
            background: var(--white);
            border-radius: 20px;
            overflow: hidden;
            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06);
            scroll-snap-align: start;
            transition: all 0.3s;
        }

        .news-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 12px 40px rgba(0, 0, 0, 0.1);
        }

        .news-thumb {
            width: 100%;
            height: 180px;
            background: linear-gradient(135deg, var(--gray-100), var(--gray-200));
            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
            overflow: hidden;
        }

        .news-thumb::before {
            content: '';
            position: absolute;
            inset: 0;
            background: linear-gradient(135deg, rgba(118, 56, 250, 0.1), rgba(255, 122, 0, 0.1));
        }

        .news-thumb-icon {
            width: 64px;
            height: 64px;
            background: linear-gradient(135deg, var(--purple), var(--orange));
            border-radius: 16px;
            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
            z-index: 1;
        }

        .news-thumb-icon svg {
            width: 32px;
            height: 32px;
            color: var(--white);
        }

        .news-content {
            padding: 24px;
        }

        .news-tags {
            display: flex;
            gap: 8px;
            margin-bottom: 12px;
            flex-wrap: wrap;
        }

        .news-tag {
            padding: 4px 10px;
            background: var(--gray-100);
            color: var(--gray-600);
            font-size: 11px;
            font-weight: 600;
            border-radius: 12px;
            text-transform: uppercase;
            letter-spacing: 0.03em;
        }

        .news-tag.purple {
            background: rgba(118, 56, 250, 0.1);
            color: var(--purple);
        }

        .news-tag.orange {
            background: rgba(255, 122, 0, 0.1);
            color: var(--orange);
        }

        .news-title {
            font-size: 16px;
            font-weight: 700;
            color: var(--black);
            line-height: 1.4;
            margin-bottom: 12px;
            display: -webkit-box;
            -webkit-line-clamp: 3;
            -webkit-box-orient: vertical;
            overflow: hidden;
        }

        .news-date {
            font-size: 13px;
            color: var(--gray-400);
        }

        /* CTA Download Section */
        .cta-download {
            background: linear-gradient(135deg, #fef7f0 0%, #fff5f5 100%);
            text-align: center;
        }

        .cta-content {
            max-width: 600px;
            margin: 0 auto;
        }

        .cta-headline {
            font-size: clamp(32px, 5vw, 48px);
            font-weight: 900;
            color: var(--black);
            margin-bottom: 12px;
