            font-size: 20px;
            color: var(--gray-600);
            margin-bottom: 36px;
        }

        .cta-buttons {
            display: flex;
            gap: 16px;
            justify-content: center;
            flex-wrap: wrap;
        }

        .store-btn {
            display: inline-flex;
            align-items: center;
            gap: 12px;
            padding: 14px 28px;
            background: var(--black);
            color: var(--white);
            border-radius: 14px;
            font-size: 15px;
            font-weight: 600;
            transition: all 0.2s;
        }

        .store-btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
        }

        .store-btn svg {
            width: 24px;
            height: 24px;
        }

        /* Footer */
        .footer {
            background: var(--black);
            color: var(--white);
            padding: 80px 24px 40px;
        }

        .footer-inner {
            max-width: 1200px;
            margin: 0 auto;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
            gap: 40px;
            padding-bottom: 60px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
        }

        .footer-col h4 {
            font-size: 13px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            margin-bottom: 20px;
            color: var(--gray-300);
        }

        .footer-col ul {
            list-style: none;
        }

        .footer-col li {
            margin-bottom: 12px;
        }

        .footer-col a {
            font-size: 14px;
            color: var(--gray-400);
            transition: color 0.2s;
        }

        .footer-col a:hover {
            color: var(--white);
        }

        .footer-col a .external-icon {
            display: inline-block;
            margin-left: 4px;
            font-size: 10px;
            opacity: 0.6;
        }

        .footer-bottom {
            padding-top: 40px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 24px;
        }

        .footer-meta {
            display: flex;
            align-items: center;
            gap: 32px;
            flex-wrap: wrap;
        }

        .language-selector {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 8px 12px;
            background: rgba(255, 255, 255, 0.1);
            border-radius: 8px;
            font-size: 13px;
            color: var(--gray-300);
            cursor: pointer;
        }

        .language-selector svg {
            width: 16px;
            height: 16px;
        }

        .social-links {
            display: flex;
            gap: 16px;
        }

        .social-link {
            width: 40px;
            height: 40px;
            background: rgba(255, 255, 255, 0.1);
            border-radius: 10px;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.2s;
        }

        .social-link:hover {
            background: var(--purple);
            transform: translateY(-2px);
        }

        .social-link svg {
            width: 20px;
            height: 20px;
            color: var(--white);
        }

        .legal-links {
